import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null,
      editEvent: null,
      errorMessage: "",
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ selectedEvent: response.data, editEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleEdit = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ editEvent: response.data, selectedEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleInputChange = (field, value) => {
    this.setState((prevState) => ({
      editEvent: { ...prevState.editEvent, [field]: value },
    }));
  };

  handleEmailChange = (index, value) => {
    const newEmailFields = [...this.state.editEvent.emailFields];
    newEmailFields[index] = value;
    this.setState((prevState) => ({
      editEvent: { ...prevState.editEvent, emailFields: newEmailFields },
    }));
  };

  addEmailField = () => {
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        emailFields: [...prevState.editEvent.emailFields, ""],
      },
    }));
  };

  removeEmailField = (index) => {
    if (index > 0) {
      this.setState((prevState) => ({
        editEvent: {
          ...prevState.editEvent,
          emailFields: prevState.editEvent.emailFields.filter((_, i) => i !== index),
        },
      }));
    }
  };

  handleParticipantChange = (index, field, value) => {
    const newParticipants = [...this.state.editEvent.participants];
    newParticipants[index][field] = value;
    this.setState((prevState) => ({
      editEvent: { ...prevState.editEvent, participants: newParticipants },
    }));
  };

  addParticipant = () => {
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        participants: [...prevState.editEvent.participants, { name: "", iin: "" }],
      },
    }));
  };

  removeParticipant = (index) => {
    if (index > 0) {
      this.setState((prevState) => ({
        editEvent: {
          ...prevState.editEvent,
          participants: prevState.editEvent.participants.filter((_, i) => i !== index),
        },
      }));
    }
  };

  handleSave = () => {
    const { eventName, eventType, eventDate, emailFields, participants } =
      this.state.editEvent;

    if (
      !eventName ||
      !eventType ||
      !eventDate ||
      emailFields.some((email) => !email) ||
      participants.some((participant) => !participant.name || !participant.iin)
    ) {
      this.setState({ errorMessage: "Все поля должны быть заполнены" });
      return;
    }

    axiosInstance
      .put(`/event/update/${this.state.editEvent.eventId}`, this.state.editEvent)
      .then(() => {
        this.setState({ editEvent: null, errorMessage: "" });
        this.componentDidMount();
      })
      .catch((error) => console.error("Ошибка при сохранении изменений:", error));
  };

  render() {
    const { events, selectedEvent, editEvent, errorMessage } = this.state;

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Дата проведения</th>
                  <th>Статус</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => (
                  <tr key={event.eventId}>
                    <td>{index + 1}</td>
                    <td>{event.eventName}</td>
                    <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                    <td>{/* Статус здесь */}</td>
                    <td>
                      <button onClick={() => this.handleView(event.eventId)}>Просмотр</button>
                      <button onClick={() => this.handleEdit(event.eventId)}>Изменить</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {editEvent && (
              <div className="editForm">
                <h1>Редактирование события</h1>
                {errorMessage && <p style={{ color: "red" }}>{errorMessage}</p>}
                <h3>Название мероприятия</h3>
                <input
                  type="text"
                  value={editEvent.eventName}
                  onChange={(e) => this.handleInputChange("eventName", e.target.value)}
                />
                <h3>Тип мероприятия</h3>
                <select
                  value={editEvent.eventType}
                  onChange={(e) => this.handleInputChange("eventType", e.target.value)}
                >
                  <option value="">Выберите тип</option>
                  <option value="seminar">Семинар</option>
                  <option value="competition">Соревнование</option>
                </select>
                <h3>Дата проведения</h3>
                <input
                  type="datetime-local"
                  value={editEvent.eventDate}
                  onChange={(e) => this.handleInputChange("eventDate", e.target.value)}
                />
                <h3>Проверяющие</h3>
                {editEvent.emailFields.map((email, index) => (
                  <div key={index}>
                    <input
                      type="text"
                      value={email}
                      onChange={(e) => this.handleEmailChange(index, e.target.value)}
                    />
                    {index > 0 && (
                      <button onClick={() => this.removeEmailField(index)}>Удалить</button>
                    )}
                  </div>
                ))}
                <button onClick={this.addEmailField}>Добавить проверяющего</button>

                <h3>Участники</h3>
                {editEvent.participants.map((participant, index) => (
                  <div key={index}>
                    <h4>Участник №{index + 1}</h4>
                    <input
                      type="text"
                      placeholder="ФИО"
                      value={participant.name}
                      onChange={(e) =>
                        this.handleParticipantChange(index, "name", e.target.value)
                      }
                    />
                    <input
                      type="text"
                      placeholder="ИИН"
                      value={participant.iin}
                      onChange={(e) =>
                        this.handleParticipantChange(index, "iin", e.target.value)
                      }
                    />
                    {index > 0 && (
                      <button onClick={() => this.removeParticipant(index)}>Удалить</button>
                    )}
                  </div>
                ))}
                <button onClick={this.addParticipant}>Добавить участника</button>
                <button onClick={this.handleSave}>Сохранить</button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
